/// 📜️ The energy document contract distinguishes fresh model imports from archived event histories.
#[semio_framework_async_macros::async_test]
async fn energy_document_history_archive_reload_example_switch_and_snapshot_import_follow_the_shared_store(){
 use semio_framework_plugin::{PluginApp as _,DslValue,kernel::Effect};
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/📜️document-history/🔣️.json")).unwrap();
 let mut app=dispatchable_app().await;let before=app.snapshot().unwrap().model.name.clone();rename(&mut app,law["documents"]["archive"]["modelName"].as_str().unwrap()).await;
 let rows=transaction_rows(&mut app).await;assert!(!rows.is_empty());let ids=rows.iter().flat_map(|row|row.mutations.iter().map(|mutation|mutation.mutation_id.clone())).collect::<Vec<_>>();let wanted=app.snapshot().unwrap().model;let files=app.document_pack().await.unwrap();
 let mut reloaded=dispatchable_app().await;semio_framework_plugin::artifact_app_laws::load_document(&mut reloaded,&files,&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await.unwrap();assert_eq!(reloaded.snapshot().unwrap().model,wanted);assert_eq!(transaction_rows(&mut reloaded).await.iter().flat_map(|row|row.mutations.iter().map(|mutation|mutation.mutation_id.clone())).collect::<Vec<_>>(),ids);
 semio_framework_plugin::artifact_app_laws::settle_history_verb(&mut reloaded,"undo",semio_framework_plugin::artifact_app_laws::meta("local").instance_id,semio_framework_plugin::artifact_app_laws::fixture_mounted_policy(),&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await;assert_eq!(reloaded.snapshot().unwrap().model.name,before);
 semio_framework_plugin::artifact_app_laws::settle_history_verb(&mut reloaded,"redo",semio_framework_plugin::artifact_app_laws::meta("local").instance_id,semio_framework_plugin::artifact_app_laws::fixture_mounted_policy(),&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await;assert_eq!(reloaded.snapshot().unwrap().model,wanted);
 let (id,_,example)=example_rows().into_iter().next().unwrap();let args=DslValue::Object(vec![("exampleId".into(),DslValue::String(id.into()))]);let result=app.handle_action(SET_ACTIVE_EXAMPLE_ACTION_ID,Some(&args),&semio_framework_plugin::artifact_app_laws::meta("local"),&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await.unwrap();let receipt=semio_framework_plugin::artifact_app_laws::settle_registered_typed_operation(&mut app,semio_framework_plugin::artifact_app_laws::meta("local").instance_id,semio_framework_plugin::artifact_app_laws::fixture_mounted_policy(),&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await.unwrap();let mut loads=result.requested_effects.into_iter().chain(receipt.effects).filter_map(|effect|match effect{Effect::LoadDocument{pack,spr}=>Some(store::os_store::serialization::ArtifactPackFiles{pack,spr,ops:String::new()}),_=>None}).collect::<Vec<_>>();assert_eq!(loads.len(),1);semio_framework_plugin::artifact_app_laws::load_document(&mut app,&loads.remove(0),&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await.unwrap();assert_eq!(app.snapshot().unwrap().model,example);assert!(transaction_rows(&mut app).await.is_empty());
 let mut imported=example;imported.name="Energy imported snapshot".into();let original=crate::energy_snapshot_with_state(ENERGY_MODEL_DOCUMENT_SCHEMA,&imported,None);let json=semio_framework_pack_json::to_json_string(&original);let decoded=crate::standards::v1::subsets::any::io::import::deserializers::artifacts::json::v_rfc8259::any::deserialize_bytes(json.as_bytes()).unwrap();assert_eq!(decoded.model,imported);assert_eq!(serde_json::from_str::<serde_json::Value>(&json).unwrap()["model"],serde_json::to_value(&imported).unwrap());assert!(crate::standards::v1::subsets::any::io::import::deserializers::artifacts::json::v_rfc8259::any::deserialize_bytes(&[255]).is_err());let Effect::LoadDocument{pack,spr}=load_document_effect(&decoded.model)else{panic!("energy import retains the shared document effect")};semio_framework_plugin::artifact_app_laws::load_document(&mut app,&store::os_store::serialization::ArtifactPackFiles{pack,spr,ops:String::new()},&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await.unwrap();assert_eq!(app.snapshot().unwrap().model,imported);assert!(transaction_rows(&mut app).await.is_empty());
 close(app);close(reloaded);eprintln!("[DEBUG] energy document archive preserves exact mutation IDs+undo/redo; example/import loads establish fresh genesis through original shared Store");
}

/// 🪞️ A registered energy editor keeps the shared Store and original composed member factories on each peer.
async fn energy_history_replica(actor:&str,uri:&str,files:Option<&store::os_store::serialization::ArtifactPackFiles>)->(EnergyEditorApp,store::os_store::backbone::MemoryBackbone){
 use semio_framework_plugin::PluginApp as _;
 let mut app=semio_framework_plugin::artifact_app_laws::new_app_with_registry_and_members::<EditorApp<EnergyModelEditor>,semio_s_artifact_stdio_semio::SemioMembers>(energy_model_manifest_for_tests,semio_framework_os_kernel::ActorId(actor.into()),semio_framework_plugin::artifact_app_laws::fixture_mounted_policy(),&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await;app.bind_instance_id(semio_framework_plugin::artifact_app_laws::meta("local").instance_id).await;if let Some(files)=files{semio_framework_plugin::artifact_app_laws::load_document(&mut app,files,&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await.unwrap();}let(backbone,probe)=store::os_store::backbone::MemoryBackbone::pair(uri,uri).await;app.attach_backbone(store::os_store::backbone::Backbones::Memory(backbone)).await.unwrap();(app,probe)
}

/// 🔀️ The actual shared memory backbone delivers retained event batches and drives its Store fold.
async fn energy_history_relay(from:&mut store::os_store::backbone::MemoryBackbone,into:&mut store::os_store::backbone::MemoryBackbone,to:&mut EnergyEditorApp){
 use store::os_store::backbone::Backbone as _;use semio_framework_plugin::PluginApp as _;
 for message in from.receive().await.unwrap(){into.send(message).await.unwrap();}to.tick_backbone(&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await.unwrap();settle(to).await;to.history_snapshot().await.unwrap();
}

/// 📡️ Short connection gaps keep local work responsive; shared inverse/history events preserve another author's fields.
#[semio_framework_async_macros::async_test]
async fn energy_document_history_two_peers_reconnect_undo_redo_and_time_travel_preserve_independent_fields(){
 use semio_framework_plugin::{PluginApp as _,DslValue};
 let law:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/📜️document-history/🔣️.json")).unwrap();let peer=&law["peer"];
 let(mut local,mut local_probe)=energy_history_replica(peer["actors"][0].as_str().unwrap(),"energy-history-local",None).await;let initial=local.document_pack().await.unwrap();let(mut remote,mut remote_probe)=energy_history_replica(peer["actors"][1].as_str().unwrap(),"energy-history-remote",Some(&initial)).await;
 slide_site_field(&mut local,"latitudeDeg",press(peer["localLatitude"].as_f64().unwrap(),"energy-peer.latitude",true)).await;let edited=transaction_rows(&mut local).await.into_iter().max_by_key(|row|row.seq).and_then(|row|row.mutations.first().map(|mutation|mutation.mutation_id.clone())).unwrap();rename(&mut local,"Energy seed").await;energy_history_relay(&mut local_probe,&mut remote_probe,&mut remote).await;
 local.detach_backbone().await.unwrap();rename(&mut local,peer["localName"].as_str().unwrap()).await;slide_site_field(&mut remote,"longitudeDeg",press(peer["remoteLongitude"].as_f64().unwrap(),"energy-peer.longitude",true)).await;assert_eq!(local.snapshot().unwrap().model.name,peer["localName"].as_str().unwrap());assert_eq!(remote.snapshot().unwrap().model.site.longitude_deg,peer["remoteLongitude"].as_f64().unwrap());
 let(backbone,mut resumed_probe)=store::os_store::backbone::MemoryBackbone::pair("energy-history-resumed","energy-history-resumed").await;local.attach_backbone(store::os_store::backbone::Backbones::Memory(backbone)).await.unwrap();energy_history_relay(&mut remote_probe,&mut resumed_probe,&mut local).await;energy_history_relay(&mut resumed_probe,&mut remote_probe,&mut remote).await;assert_eq!(local.snapshot().unwrap().model,remote.snapshot().unwrap().model);
 semio_framework_plugin::artifact_app_laws::settle_history_verb(&mut local,"undo",semio_framework_plugin::artifact_app_laws::meta("local").instance_id,semio_framework_plugin::artifact_app_laws::fixture_mounted_policy(),&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await;assert_eq!(local.snapshot().unwrap().model.name,"Energy seed");assert_eq!(local.snapshot().unwrap().model.site.longitude_deg,peer["remoteLongitude"].as_f64().unwrap());energy_history_relay(&mut resumed_probe,&mut remote_probe,&mut remote).await;
 semio_framework_plugin::artifact_app_laws::settle_history_verb(&mut local,"redo",semio_framework_plugin::artifact_app_laws::meta("local").instance_id,semio_framework_plugin::artifact_app_laws::fixture_mounted_policy(),&mut semio_framework_plugin::artifact_app_laws::fixture_identity()).await;energy_history_relay(&mut resumed_probe,&mut remote_probe,&mut remote).await;assert_eq!(local.snapshot().unwrap().model,remote.snapshot().unwrap().model);
 history_edit(&mut local,"historyEditBegin",vec![("mutationId",DslValue::String(edited))]).await;history_edit(&mut local,"historyEditInput",vec![("path",DslValue::String("/newLatitudeDeg".into())),("value",DslValue::float(peer["revisedLatitude"].as_f64().unwrap()))]).await;history_edit(&mut local,"historyEditAccept",Vec::new()).await;pump_time_travel(&mut local,|stage|stage!=Some(semio_framework::kernel::HistoryTimeTravelStage::Replaying)).await;assert_eq!(local.snapshot().unwrap().model.site.latitude_deg,peer["localLatitude"].as_f64().unwrap());history_edit(&mut local,"historyEditFinalize",Vec::new()).await;history_edit(&mut local,"historyEditCommit",vec![("choice",DslValue::String("overwrite".into()))]).await;pump_time_travel(&mut local,|stage|stage.is_none()).await;energy_history_relay(&mut resumed_probe,&mut remote_probe,&mut remote).await;
 let head=local.snapshot().unwrap().model;assert_eq!(head,remote.snapshot().unwrap().model);assert_eq!((head.name.as_str(),head.site.longitude_deg,head.site.latitude_deg),(peer["expected"]["name"].as_str().unwrap(),peer["expected"]["longitude"].as_f64().unwrap(),peer["expected"]["latitude"].as_f64().unwrap()));
 drop((local_probe,resumed_probe,remote_probe));close(local);close(remote);eprintln!("[DEBUG] energy actual two-peer short-gap reconnect converges; local undo/redo and shared history supersede retain independent remote longitude");
}

